package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import jakarta.servlet.Filter;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import org.springframework.context.annotation.*;import org.springframework.core.env.MapPropertySource;import org.springframework.mock.web.MockServletContext;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.MeterRegistry;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class GitHubWorkSecurityTest {
 @Configuration(proxyBeanMethods=false) @EnableWebMvc @EnableWebSecurity @Import({SecurityConfiguration.class,GitHubController.class,GitHubWorkController.class,GitHubErrors.class})
 static class Web {@Bean GitHubStore store(){return mock(GitHubStore.class);}@Bean GitHubClient remote(){return mock(GitHubClient.class);}@Bean SpaceAuthorizationClient authority(){return mock(SpaceAuthorizationClient.class);}@Bean GitHubWorkStore workStore(){return mock(GitHubWorkStore.class);}@Bean GitHubWorkClient workClient(){return mock(GitHubWorkClient.class);}@Bean MeterRegistry metrics(){return new SimpleMeterRegistry();}}
 AnnotationConfigWebApplicationContext context;MockMvc mvc;GitHubStore store;GitHubClient remote;SpaceAuthorizationClient authority;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space=ids.next(),repo=ids.next(),actor=ids.next();String token="a".repeat(43),path="/api/spaces/"+space+"/github/repositories/"+repo+"/work-items";
 void start(boolean enabled){if(context!=null)context.close();context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("github-sync-security",Map.of("brain.integration.api.enabled",Boolean.toString(enabled),"brain.integration.activity-export.enabled","false","brain.integration.browser-origin","https://localhost:8443")));context.register(Web.class);context.refresh();store=context.getBean(GitHubStore.class);remote=context.getBean(GitHubClient.class);authority=context.getBean(SpaceAuthorizationClient.class);mvc=MockMvcBuilders.webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",Filter.class)).build();when(authority.authorize(eq(space),eq(token),eq(false),anyString())).thenReturn(actor);}
 @AfterEach void close(){if(context!=null)context.close();}

 GitHubWorkStore work(){return context.getBean(GitHubWorkStore.class);}GitHubWorkClient workClient(){return context.getBean(GitHubWorkClient.class);}Cookie cookie(){return new Cookie("__Host-brain_guest",token);}
 @Test void actualFilterAllowsEnabledTypedReadsAndFreshRevocationStopsCanonicalStore()throws Exception{start(true);when(work().state(space,repo,"ISSUE")).thenReturn(new GitHubWorkStore.State(repo,space,"ISSUE",0,null,"ACTIVE"));mvc.perform(get(path+"/ISSUE/sync-state").secure(true).cookie(cookie())).andExpect(status().isOk()).andExpect(header().string("ETag","\"ghw0\"")).andExpect(header().string("Cache-Control","no-store"));when(authority.authorize(eq(space),eq(token),eq(false),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));mvc.perform(get(path+"/ISSUE/sync-state").secure(true).cookie(cookie())).andExpect(status().isForbidden());verify(work()).state(space,repo,"ISSUE");verifyNoMoreInteractions(work());verifyNoInteractions(remote,workClient());}
 @Test void disabledUnknownAndUnsupportedMethodsAreBlockedButWritersReachStrongCasGuards()throws Exception{start(false);mvc.perform(get(path).secure(true).cookie(cookie())).andExpect(status().isForbidden());start(true);when(authority.authorize(eq(space),eq(token),eq(true),anyString())).thenReturn(actor);String sync=path+"/PULL_REQUEST/sync";mvc.perform(post(sync).secure(true).cookie(cookie()).header("Origin","https://localhost:8443").header("Idempotency-Key","b".repeat(32)).contentType("application/json").content("{}")).andExpect(status().isPreconditionRequired());for(String tag:List.of("\"ghr1\"","W/\"ghw0\"","\"ghw00\"","*")){mvc.perform(post(sync).secure(true).cookie(cookie()).header("Origin","https://localhost:8443").header("Idempotency-Key","b".repeat(32)).header("If-Match",tag).contentType("application/json").content("{}")).andExpect(status().isBadRequest());}mvc.perform(post(sync).secure(true).cookie(cookie()).header("Idempotency-Key","b".repeat(32)).header("If-Match","\"ghw0\"").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(delete(path+"/"+actor).secure(true).cookie(cookie())).andExpect(status().isForbidden());mvc.perform(get(path+"/extra/extra").secure(true).cookie(cookie())).andExpect(status().isForbidden());verifyNoInteractions(work(),remote,workClient());}
 @Test void exactReplayReturnsCurrentStateWithoutAnyExternalCallOrMutation()throws Exception{start(true);when(authority.authorize(eq(space),eq(token),eq(true),anyString())).thenReturn(actor);var state=new GitHubWorkStore.State(repo,space,"ISSUE",2,"2026-11-01T00:00:00Z","RETIRED");var receipt=new GitHubWorkStore.Receipt(actor,repo,"ISSUE",1,"2026-11-01T00:00:00Z",0,0,0,0,0,false);when(work().replay(space,repo,"ISSUE",actor,"b".repeat(32),0)).thenReturn(new GitHubWorkStore.Synced(state,receipt,true));mvc.perform(post(path+"/ISSUE/sync").secure(true).cookie(cookie()).header("Origin","https://localhost:8443").header("Idempotency-Key","b".repeat(32)).header("If-Match","\"ghw0\"").contentType("application/json").content("{}")).andExpect(status().isOk()).andExpect(header().string("ETag","\"ghw2\"")).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(store,remote,workClient());}
 @Test void authorityChangedDuringFetchPreventsAnyDomainWrite()throws Exception{start(true);when(authority.authorize(eq(space),eq(token),eq(true),anyString())).thenReturn(actor,ids.next());when(work().state(space,repo,"ISSUE")).thenReturn(new GitHubWorkStore.State(repo,space,"ISSUE",0,null,"ACTIVE"));var parent=new GitHubStore.Repository(repo,space,"PRIVATE","1296269","octocat/Hello-World","https://github.com/octocat/Hello-World","main","ACTIVE",1,actor,"2026-11-01T00:00:00Z","2026-11-01T00:00:00Z",null);when(store.get(space,repo)).thenReturn(parent);var source=new GitHubClient.Repository("1296269",parent.fullName(),parent.url(),"main");when(remote.repository("https://github.com/octocat/hello-world")).thenReturn(source);when(workClient().fetch(source,"ISSUE")).thenReturn(new GitHubWorkClient.Batch(source,"ISSUE",List.of(),0,false));mvc.perform(post(path+"/ISSUE/sync").secure(true).cookie(cookie()).header("Origin","https://localhost:8443").header("Idempotency-Key","b".repeat(32)).header("If-Match","\"ghw0\"").contentType("application/json").content("{}")).andExpect(status().isForbidden());verify(work(),never()).sync(any(),any(),any(),any(),any(),anyLong(),any(),any());}
}
